const body = $json.body ?? $json ?? {};
const confirm = String(body.confirm ?? '').trim();

if (confirm !== 'CLEAN_RENOVATION_DEV_SCHEMA') {
  throw new Error('Confirmation mismatch. Send confirm=CLEAN_RENOVATION_DEV_SCHEMA to clean renovation_dev.');
}

return [{
  json: {
    confirmed: true,
    schema: 'renovation_dev',
    requested_at: new Date().toISOString()
  }
}];
